import{_ as t,o as i,c as a,ag as o}from"./chunks/framework.CPvOxTBX.js";const m=JSON.parse('{"title":"Dictionary formats","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dictionary-formats.md","filePath":"guide/dictionary-formats.md","lastUpdated":1793449457000}'),s={name:"guide/dictionary-formats.md"};function d(r,e,n,c,l,h){return i(),a("div",null,e[0]||(e[0]=[o(`<h1 id="dictionary-formats" tabindex="-1">Dictionary formats <a class="header-anchor" href="#dictionary-formats" aria-label="Permalink to &quot;Dictionary formats&quot;">​</a></h1><p>Ciyue reads three dictionary families: <strong>MDict</strong> (<code>.mdx</code> / <code>.mdd</code>), <strong>StarDict</strong> (<code>.ifo</code> / <code>.idx</code> / <code>.dict</code>), and <strong>ZIM</strong> (<code>.zim</code>). They hold headwords, HTML or plain-text definitions, and the pictures and audio those definitions reference.</p><p>This page describes what is inside each format, what Ciyue reads, and how to move a dictionary from one format to the other.</p><div class="warning custom-block"><p class="custom-block-title">One dictionary per stem</p><p>Ciyue identifies a dictionary by its path without the extension, so <code>dict.mdx</code> and <code>dict.ifo</code> in the same folder count as the same dictionary: only the MDX one is imported. To keep both, give them different base names — <code>dict-mdx.mdx</code> and <code>dict-stardict.ifo</code>, for example.</p></div><h2 id="mdict" tabindex="-1">MDict <a class="header-anchor" href="#mdict" aria-label="Permalink to &quot;MDict&quot;">​</a></h2><p>An MDict dictionary is one <code>.mdx</code> file plus optional resource files:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>name.mdx</code></td><td>headwords and definitions</td></tr><tr><td><code>name.mdd</code></td><td>pictures, audio, CSS, JS</td></tr><tr><td><code>name.1.mdd</code>, <code>name.2.mdd</code></td><td>further resource archives (the <code>1</code> and <code>2</code> are part of the name)</td></tr></tbody></table><p>They all share the base name. <code>name.mdx</code> is the only file Ciyue needs to import the dictionary, but resources are only found when the <code>.mdd</code> files sit next to it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>MDict itself is closed-source freeware (Octopus Studio) and the format has never been published as a specification, so every open-source reader — including the one Ciyue uses — was reverse-engineered from the files. That is also why support differs between tools. Versions 1.2 and 2.0 (<code>GeneratedByEngineVersion</code> in the header) are what everything handles; 3.0 changes the encoding rules and is only partially supported, though dictionaries built with it are rare.</p></div><p>Inside, <code>.mdx</code> is a 4-byte header length, an XML header in UTF-16LE (<code>Title</code>, <code>Description</code>, <code>Encoding</code>, <code>StyleSheet</code>, …), then the key index and the record blocks. Both are compressed in chunks, so a lookup only inflates the block it needs. <code>.mdd</code> uses the same container with file paths as keys. Definitions are HTML in practice, and resource references use relative names.</p><p>Ciyue reads <code>.mdd</code> and split <code>.N.mdd</code> archives, and falls back to loose files next to the <code>.mdx</code> when a resource is in neither. An MDX compressed with LZO is rejected on import with an &quot;unsupported compression&quot; message: re-compress it with zlib or convert the file.</p><h3 id="on-the-desktop-goldendict-ng-is-the-reference" tabindex="-1">On the desktop, GoldenDict-ng is the reference <a class="header-anchor" href="#on-the-desktop-goldendict-ng-is-the-reference" aria-label="Permalink to &quot;On the desktop, GoldenDict-ng is the reference&quot;">​</a></h3><p>MDict itself renders entries with the old Internet Explorer WebBrowser control (the IE7/8 generation, with JavaScript stopping at ES5), so a modern <code>.mdx</code> that relies on flexbox, <code>word-break</code>, <code>localStorage</code> or ES6 does not display correctly in the app that defined the format. Since GoldenDict-ng is what most people actually run on a PC, it — not MDict — has become the de facto reference for new dictionaries. The <a href="https://lib.rs/crates/pangloss" target="_blank" rel="noreferrer"><code>pangloss</code></a> converter says so plainly:</p><blockquote><p>Every non-trivial format targets a concrete reader, f.e. goldendict-ng in the case of Mdict. While other readers may be able to import the format, they usually don&#39;t support the same range of features.</p></blockquote><table tabindex="0"><thead><tr><th>Format</th><th>Target reader</th></tr></thead><tbody><tr><td>Yomitan</td><td>Yomitan</td></tr><tr><td>StarDict</td><td>KOReader</td></tr><tr><td>MDict</td><td>GoldenDict-ng</td></tr><tr><td>DSL (read only)</td><td>GoldenDict-ng</td></tr></tbody></table><p>Traces of this &quot;written for GoldenDict-ng, not MDict&quot; habit show up everywhere. For example, many third-party-packaged <code>.mdx</code> files carry <code>bword://word</code> links directly — <code>bword://</code> is Babylon&#39;s <code>.bgl</code> cross-reference scheme, which the original MDict does not understand at all; it only works because GoldenDict-ng treats <code>bword://</code> and <code>entry://</code> as the same scheme. In other words, even files in MDict&#39;s own format are authored against GoldenDict-ng&#39;s behaviour.</p><p>When a dictionary &quot;looks broken&quot; in one app, first check which reader it was built for: entries are usually written against the newest engine, not the oldest.</p><h2 id="stardict" tabindex="-1">StarDict <a class="header-anchor" href="#stardict" aria-label="Permalink to &quot;StarDict&quot;">​</a></h2><p>StarDict is a folder of small files that share a base name:</p><table tabindex="0"><thead><tr><th>File</th><th>Required</th><th>Contents</th></tr></thead><tbody><tr><td><code>name.ifo</code></td><td>yes</td><td>plain-text metadata: <code>bookname</code>, <code>wordcount</code>, <code>idxfilesize</code>, <code>sametypesequence</code>, …</td></tr><tr><td><code>name.idx</code></td><td>yes</td><td>headword index</td></tr><tr><td><code>name.dict</code></td><td>yes</td><td>definitions</td></tr><tr><td><code>name.syn</code></td><td>no</td><td>synonym index</td></tr></tbody></table><p><code>bookname</code> is the title Ciyue shows. Each <code>.idx</code> record is the headword as UTF-8, a <code>\\0</code>, then a 4-byte big-endian offset and a 4-byte big-endian length into <code>.dict</code>. Records are sorted by byte value, which is what makes the binary search possible. A <code>.ifo</code> that carries <code>idxoffsetbits=64</code> uses 8-byte offsets instead (the StarDict 3.0 layout).</p><p><code>.dict</code> holds the definitions. With <code>sametypesequence</code> set, every record is a concatenation of fields of exactly those types and carries no type bytes; without it, every field is prefixed by one type byte. The common types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>m</code></td><td>plain text</td></tr><tr><td><code>h</code></td><td>HTML</td></tr><tr><td><code>g</code></td><td>Pango markup</td></tr><tr><td><code>x</code></td><td>XDXF</td></tr><tr><td><code>t</code></td><td>phonetic transcription</td></tr><tr><td><code>y</code></td><td>Chinese Pinyin / Japanese kana</td></tr><tr><td><code>r</code></td><td>list of resource files</td></tr><tr><td><code>W</code></td><td>WAV audio</td></tr><tr><td><code>P</code></td><td>picture</td></tr></tbody></table><p><code>.idx</code>, <code>.syn</code> and <code>.dict</code> may be stored compressed: <code>.idx.gz</code> / <code>.syn.gz</code> (gzip) and <code>.dict.dz</code> (dictzip — a gzip container whose blocks can be read independently, so lookups stay random-access). Ciyue reads all three spellings.</p><h3 id="resource-files-res-and-res-zip" tabindex="-1">Resource files: <code>res/</code> and <code>res.zip</code> <a class="header-anchor" href="#resource-files-res-and-res-zip" aria-label="Permalink to &quot;Resource files: \`res/\` and \`res.zip\`&quot;">​</a></h3><p>StarDict itself has no resource container: pictures and audio sit in a <code>res/</code> folder next to the dictionary, and entries reference them as <code>res/pic.png</code> or <code>pic.png</code>.</p><p>GoldenDict-ng extended this by letting the same folder ship as a zip, with no unpacking:</p><table tabindex="0"><thead><tr><th>Path</th><th>Note</th></tr></thead><tbody><tr><td><code>res/</code></td><td>plain directory</td></tr><tr><td><code>res.zip</code></td><td>archive with the contents of <code>res/</code> at its root</td></tr><tr><td><code>name.res.zip</code></td><td>same, named after the dictionary</td></tr></tbody></table><p>The archive must not add a top-level <code>res/</code> of its own — its root <em>is</em> <code>res/</code>. Ciyue looks for <code>res/</code>, then <code>res.zip</code>, <code>name.res.zip</code> and <code>res/res.zip</code>, and inside an archive accepts both <code>pic.png</code> and <code>res/pic.png</code>, so a zip built for GoldenDict-ng works as it is.</p><h2 id="which-one-to-use" tabindex="-1">Which one to use <a class="header-anchor" href="#which-one-to-use" aria-label="Permalink to &quot;Which one to use&quot;">​</a></h2><ul><li><strong>MDict</strong> compresses better and is a single file, which is why most published dictionaries ship that way. It is also harder to open: reading or patching an <code>.mdx</code> needs a tool.</li><li><strong>StarDict</strong> is plain files and a tiny index format, so it is easy to inspect, diff and patch by hand, and almost every open-source dictionary app reads it. With <code>res.zip</code> and <code>.dict.dz</code> it no longer costs thousands of small files.</li></ul><h2 id="converting" tabindex="-1">Converting <a class="header-anchor" href="#converting" aria-label="Permalink to &quot;Converting&quot;">​</a></h2><p>Ciyue writes neither format. Use the tools below.</p><h3 id="mdict-→-stardict-pyglossary" tabindex="-1">MDict → StarDict (pyglossary) <a class="header-anchor" href="#mdict-→-stardict-pyglossary" aria-label="Permalink to &quot;MDict → StarDict (pyglossary)&quot;">​</a></h3><p><a href="https://github.com/ilius/pyglossary" target="_blank" rel="noreferrer">pyglossary</a> needs Python 3.12 or newer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyglossary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pyglossary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.ifo</span></span></code></pre></div><p>Formats are detected from the extensions; pass <code>--read-format</code> / <code>--write-format</code> when they are ambiguous (<code>pyglossary --help</code> lists the names). Useful options:</p><ul><li><code>--sqlite</code> — keep the intermediate data in SQLite instead of RAM; use it for large dictionaries.</li><li><code>--no-interactive</code> — for scripts; requires both file names.</li><li><code>--remove-html-all</code> — strip HTML from the definitions (needs <code>lxml</code> and <code>beautifulsoup4</code>); usually you want to keep it.</li></ul><p>StarDict output has to be sorted, so pyglossary may switch to the SQLite mode on its own.</p><h3 id="stardict-→-mdict-mdict-utils" tabindex="-1">StarDict → MDict (mdict-utils) <a class="header-anchor" href="#stardict-→-mdict-mdict-utils" aria-label="Permalink to &quot;StarDict → MDict (mdict-utils)&quot;">​</a></h3><p>pyglossary can read MDict but not write it. To go the other way, <a href="https://github.com/zhansliu/mdict-utils" target="_blank" rel="noreferrer">mdict-utils</a> packs the plain-text format that MDict tools use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdict-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My dictionary&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span></code></pre></div><p><code>source.txt</code> holds one record per headword: the headword on its own line, the definition after it, and a line with <code>&lt;/&gt;</code> between records.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>word</span></span>
<span class="line"><span>&lt;p&gt;definition&lt;/p&gt;</span></span>
<span class="line"><span>&lt;/&gt;</span></span></code></pre></div><p>pyglossary&#39;s tab-separated output is one small step away from that; a short script that splits each line and writes <code>&lt;/&gt;</code> between entries is usually all it takes.</p><p>The same tool is handy for inspection:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # header</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # first headwords</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> word</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # one entry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> book.mdx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # unpack entries and .mdd resources</span></span></code></pre></div><h2 id="zim" tabindex="-1">ZIM <a class="header-anchor" href="#zim" aria-label="Permalink to &quot;ZIM&quot;">​</a></h2><p>The <strong>ZIM</strong> format (<code>.zim</code>, openZIM) is an open, highly compressed archive format originally designed to distribute Wikipedia, Wiktionary, Project Gutenberg, and other wiki or educational content offline.</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>name.zim</code></td><td>Self-contained single-file archive containing articles, media, CSS, JS, and metadata</td></tr></tbody></table><p>A ZIM dictionary is a single self-contained file. Ciyue indexes article headwords and redirects, serves embedded media (images, stylesheets, fonts, audio, video), and caches the index into <code>.cidx</code> for instant startup.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ZIM archives are published by <a href="https://www.kiwix.org/" target="_blank" rel="noreferrer">Kiwix</a> and <a href="https://openzim.org/" target="_blank" rel="noreferrer">openZIM</a>. You can download offline copies of Wikipedia, Wiktionary, Wikibooks, Stack Exchange, and more in hundreds of languages.</p></div><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Keep the base name.</strong> Renaming one file of a pair (<code>.mdx</code> + <code>.mdd</code>) or a trio (<code>.ifo</code> + <code>.idx</code> + <code>.dict</code>) breaks the dictionary; rename them together.</li><li><strong><code>res.zip</code> without an outer folder</strong> if the dictionary also has to work in GoldenDict-ng.</li><li><strong>Check the title after converting.</strong> It comes from the MDict header or the StarDict <code>bookname</code>, whichever the converter wrote; an empty one falls back to the file name.</li><li><strong>Audio may stop working.</strong> pyglossary rewrites MDict&#39;s <code>&lt;a href=&quot;sound://…&quot;&gt;</code> into <code>&lt;audio src=&quot;…&quot;&gt;</code>, which some readers do not render. If the speaker icon disappears after conversion, that is why.</li></ul><h2 id="where-to-find-dictionaries" tabindex="-1">Where to find dictionaries <a class="header-anchor" href="#where-to-find-dictionaries" aria-label="Permalink to &quot;Where to find dictionaries&quot;">​</a></h2><ul><li><a href="https://forum.freemdict.com/" target="_blank" rel="noreferrer">FreeMdict forum</a> — the largest community for MDX/StarDict dictionaries, with format discussions and conversion recipes.</li><li><a href="https://xiaoyifang.github.io/goldendict-ng/dictformats/" target="_blank" rel="noreferrer">GoldenDict-ng&#39;s format notes</a> — the reference for <code>res.zip</code>, dictzip and the other formats it reads.</li></ul><p>Respect the licence of whatever you download or convert; many dictionaries are only free for personal use.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting started</a> — importing a dictionary.</li><li><a href="./word-forms.html">Word-form lookup</a> — Hunspell files, which are separate from the dictionary format itself.</li><li><a href="./faq.html">FAQ</a> — import errors and display problems.</li></ul>`,59)]))}const u=t(s,[["render",d]]);export{m as __pageData,u as default};
